# Optional hover-animation CSS (source: ../../styles/hifi-anim.css). Inline this
# into a <style> block to animate hi-fi icons on hover/focus; it is inert unless
# included, and self-disables under prefers-reduced-motion.
HIFI_ANIM_CSS: str = "/*\n * persona-icons — hi-fi hover micro-interactions.\n *\n * SOURCE OF TRUTH for icon animation. `scripts/gen.mjs` copies this verbatim\n * into the Python package (as HIFI_ANIM_CSS) so persona-council and\n * persona-website share one animation layer. Authored by hand — safe to edit.\n *\n * How it hooks in\n *   • Every hi-fi <svg> carries `pi-hifi pi-hifi-<name>` (added by the codegen).\n *   • Animatable sub-parts carry `data-part=\"…\"` in icons.data.mjs.\n *   • Animations fire when the icon itself is hovered/focused, OR when an\n *     ancestor with class `.pi-hover` is hovered (use it on a card/button to\n *     drive the icon inside). Including this file is the opt-in; without it the\n *     classes are inert and icons stay perfectly still.\n *\n * Everything lives inside prefers-reduced-motion: no-preference, so users who\n * ask for reduced motion get the static icons.\n */\n@media (prefers-reduced-motion: no-preference) {\n  /* Transform about each element's own box by default; smooth, GPU-friendly. */\n  .pi-hifi * { transform-box: fill-box; }\n  .pi-hifi [data-part],\n  .pi-hifi rect,\n  .pi-hifi circle,\n  .pi-hifi path { transition: transform .38s cubic-bezier(.34, 1.4, .64, 1),\n                              fill-opacity .38s ease, stroke-opacity .38s ease; }\n\n  /* ── chrome / UI ──────────────────────────────────────────────────────── */\n\n  /* overview — four tiles pop in, staggered */\n  .pi-hifi-overview rect { transition: transform .3s cubic-bezier(.34, 1.56, .64, 1); }\n  :is(.pi-hifi-overview:hover, .pi-hifi-overview:focus-visible, .pi-hover:hover .pi-hifi-overview) rect { animation: pi-pop .42s both; }\n  :is(.pi-hifi-overview:hover, .pi-hifi-overview:focus-visible, .pi-hover:hover .pi-hifi-overview) rect:nth-of-type(2) { animation-delay: .05s; }\n  :is(.pi-hifi-overview:hover, .pi-hifi-overview:focus-visible, .pi-hover:hover .pi-hifi-overview) rect:nth-of-type(3) { animation-delay: .1s; }\n  :is(.pi-hifi-overview:hover, .pi-hifi-overview:focus-visible, .pi-hover:hover .pi-hifi-overview) rect:nth-of-type(4) { animation-delay: .15s; }\n\n  /* personas — the back person eases in */\n  .pi-hifi-personas [data-part=\"peer\"] { opacity: 1; }\n  :is(.pi-hifi-personas:hover, .pi-hifi-personas:focus-visible, .pi-hover:hover .pi-hifi-personas) [data-part=\"peer\"] { animation: pi-peer-in .45s both; }\n\n  /* councils — the three dots type */\n  :is(.pi-hifi-councils:hover, .pi-hifi-councils:focus-visible, .pi-hover:hover .pi-hifi-councils) circle:nth-of-type(2) { animation: pi-typing .9s ease-in-out infinite; }\n  :is(.pi-hifi-councils:hover, .pi-hifi-councils:focus-visible, .pi-hover:hover .pi-hifi-councils) circle:nth-of-type(3) { animation: pi-typing .9s ease-in-out .15s infinite; }\n  :is(.pi-hifi-councils:hover, .pi-hifi-councils:focus-visible, .pi-hover:hover .pi-hifi-councils) circle:nth-of-type(4) { animation: pi-typing .9s ease-in-out .3s infinite; }\n\n  /* syntheses — the top layer lifts */\n  :is(.pi-hifi-syntheses:hover, .pi-hifi-syntheses:focus-visible, .pi-hover:hover .pi-hifi-syntheses) [data-part=\"top\"] { transform: translateY(-2.5px); }\n\n  /* projects — connectors draw, nodes pulse */\n  .pi-hifi-projects path { stroke-dasharray: 64; }\n  :is(.pi-hifi-projects:hover, .pi-hifi-projects:focus-visible, .pi-hover:hover .pi-hifi-projects) path { animation: pi-draw .6s ease forwards; }\n  :is(.pi-hifi-projects:hover, .pi-hifi-projects:focus-visible, .pi-hover:hover .pi-hifi-projects) circle { animation: pi-pop .4s both; }\n  :is(.pi-hifi-projects:hover, .pi-hifi-projects:focus-visible, .pi-hover:hover .pi-hifi-projects) circle:nth-of-type(2) { animation-delay: .08s; }\n  :is(.pi-hifi-projects:hover, .pi-hifi-projects:focus-visible, .pi-hover:hover .pi-hifi-projects) circle:nth-of-type(3) { animation-delay: .16s; }\n\n  /* memory — the brain \"lights up\" and the sulci shimmer */\n  :is(.pi-hifi-memory:hover, .pi-hifi-memory:focus-visible, .pi-hover:hover .pi-hifi-memory) [data-part=\"brain\"] { animation: pi-brain 1.1s ease-in-out infinite; }\n  :is(.pi-hifi-memory:hover, .pi-hifi-memory:focus-visible, .pi-hover:hover .pi-hifi-memory) [data-part=\"sulci\"] { animation: pi-shimmer 1.1s ease-in-out infinite; }\n\n  /* panel — the menu lines slide in */\n  :is(.pi-hifi-panel:hover, .pi-hifi-panel:focus-visible, .pi-hover:hover .pi-hifi-panel) [data-part=\"lines\"] { animation: pi-slide-x .45s ease both; }\n\n  /* settings — the cog turns (continuous: an 8-tooth gear has 45° symmetry, so\n     any fixed multiple-of-45° rotation would look identical and read as static) */\n  :is(.pi-hifi-settings:hover, .pi-hifi-settings:focus-visible, .pi-hover:hover .pi-hifi-settings) [data-part=\"gear\"] { animation: pi-spin 3.5s linear infinite; }\n\n  /* sun — rays splay and rotate, core swells */\n  .pi-hifi-sun [data-part=\"rays\"] { transition: transform .5s cubic-bezier(.34, 1.4, .64, 1); }\n  :is(.pi-hifi-sun:hover, .pi-hifi-sun:focus-visible, .pi-hover:hover .pi-hifi-sun) [data-part=\"rays\"] { transform: rotate(45deg) scale(1.06); }\n  :is(.pi-hifi-sun:hover, .pi-hifi-sun:focus-visible, .pi-hover:hover .pi-hifi-sun) [data-part=\"core\"] { transform: scale(1.12); }\n\n  /* moon — a gentle tilt */\n  .pi-hifi-moon [data-part=\"moon\"] { transform-box: view-box; transform-origin: 24px 24px; }\n  :is(.pi-hifi-moon:hover, .pi-hifi-moon:focus-visible, .pi-hover:hover .pi-hifi-moon) [data-part=\"moon\"] { transform: rotate(-12deg); }\n\n  /* monitor — the screen switches on */\n  :is(.pi-hifi-monitor:hover, .pi-hifi-monitor:focus-visible, .pi-hover:hover .pi-hifi-monitor) [data-part=\"screen\"] { animation: pi-screen 1.4s ease-in-out infinite; }\n\n  /* chevron — bounces down */\n  :is(.pi-hifi-chevron:hover, .pi-hifi-chevron:focus-visible, .pi-hover:hover .pi-hifi-chevron) path { animation: pi-bounce-y .5s ease; }\n\n  /* back — nudges left */\n  :is(.pi-hifi-back:hover, .pi-hifi-back:focus-visible, .pi-hover:hover .pi-hifi-back) path { transform: translateX(-3px); }\n\n  /* analytics — bars grow from the baseline, staggered */\n  .pi-hifi-analytics rect { transform-origin: bottom; }\n  :is(.pi-hifi-analytics:hover, .pi-hifi-analytics:focus-visible, .pi-hover:hover .pi-hifi-analytics) rect { animation: pi-grow-y .5s cubic-bezier(.34, 1.4, .64, 1) both; }\n  :is(.pi-hifi-analytics:hover, .pi-hifi-analytics:focus-visible, .pi-hover:hover .pi-hifi-analytics) rect:nth-of-type(2) { animation-delay: .08s; }\n  :is(.pi-hifi-analytics:hover, .pi-hifi-analytics:focus-visible, .pi-hover:hover .pi-hifi-analytics) rect:nth-of-type(3) { animation-delay: .16s; }\n\n  /* star — twinkles */\n  :is(.pi-hifi-star:hover, .pi-hifi-star:focus-visible, .pi-hover:hover .pi-hifi-star) path { transform: scale(1.1) rotate(14deg); }\n\n  /* bulb — the idea switches on */\n  :is(.pi-hifi-bulb:hover, .pi-hifi-bulb:focus-visible, .pi-hover:hover .pi-hifi-bulb) [data-part=\"bulb\"] { animation: pi-glow 1.3s ease-in-out infinite; }\n  :is(.pi-hifi-bulb:hover, .pi-hifi-bulb:focus-visible, .pi-hover:hover .pi-hifi-bulb) [data-part=\"filament\"] { animation: pi-shimmer 1.3s ease-in-out infinite; }\n\n  /* target — rings lock outward */\n  :is(.pi-hifi-target:hover, .pi-hifi-target:focus-visible, .pi-hover:hover .pi-hifi-target) circle { animation: pi-ring 1.1s ease-out infinite; }\n  :is(.pi-hifi-target:hover, .pi-hifi-target:focus-visible, .pi-hover:hover .pi-hifi-target) circle:nth-of-type(2) { animation-delay: .12s; }\n  :is(.pi-hifi-target:hover, .pi-hifi-target:focus-visible, .pi-hover:hover .pi-hifi-target) circle:nth-of-type(3) { animation-delay: .24s; }\n\n  /* compass — the needle settles like a real one */\n  .pi-hifi-compass [data-part=\"needle\"] { transform-box: view-box; transform-origin: 24px 24px; }\n  :is(.pi-hifi-compass:hover, .pi-hifi-compass:focus-visible, .pi-hover:hover .pi-hifi-compass) [data-part=\"needle\"] { animation: pi-wobble .8s cubic-bezier(.36, .07, .19, .97); }\n\n  /* search — the lens scans */\n  .pi-hifi-search [data-part=\"lens\"] { transform-box: view-box; transform-origin: 21px 21px; }\n  :is(.pi-hifi-search:hover, .pi-hifi-search:focus-visible, .pi-hover:hover .pi-hifi-search) [data-part=\"lens\"] { animation: pi-scan .9s ease-in-out; }\n\n  /* ── status & actions ─────────────────────────────────────────────────── */\n\n  /* check — draws itself */\n  .pi-hifi-check path { stroke-dasharray: 40; }\n  :is(.pi-hifi-check:hover, .pi-hifi-check:focus-visible, .pi-hover:hover .pi-hifi-check) path { animation: pi-draw .5s ease forwards; }\n\n  /* circle — soft pulse */\n  :is(.pi-hifi-circle:hover, .pi-hifi-circle:focus-visible, .pi-hover:hover .pi-hifi-circle) circle { transform: scale(1.07); }\n\n  /* half — the fill flips to the other side */\n  .pi-hifi-half path { transform-box: view-box; transform-origin: 24px 24px; transition: transform .5s cubic-bezier(.4, 0, .2, 1); }\n  :is(.pi-hifi-half:hover, .pi-hifi-half:focus-visible, .pi-hover:hover .pi-hifi-half) path { transform: rotate(180deg); }\n\n  /* alert — the mark gives a quick shake */\n  .pi-hifi-alert [data-part=\"mark\"] { transform-box: view-box; transform-origin: 24px 24px; }\n  :is(.pi-hifi-alert:hover, .pi-hifi-alert:focus-visible, .pi-hover:hover .pi-hifi-alert) [data-part=\"mark\"] { animation: pi-shake .5s ease; }\n\n  /* close — pops (a symmetric X is unchanged by 90°/180° rotation, so scale) */\n  :is(.pi-hifi-close:hover, .pi-hifi-close:focus-visible, .pi-hover:hover .pi-hifi-close) path { transform: scale(1.16); }\n\n  /* plus — grows (a + is unchanged by 90° rotation, so scale to read as \"add\") */\n  :is(.pi-hifi-plus:hover, .pi-hifi-plus:focus-visible, .pi-hover:hover .pi-hifi-plus) path { transform: scale(1.18); }\n\n  /* external — the arrow shoots out */\n  :is(.pi-hifi-external:hover, .pi-hifi-external:focus-visible, .pi-hover:hover .pi-hifi-external) path:nth-of-type(2),\n  :is(.pi-hifi-external:hover, .pi-hifi-external:focus-visible, .pi-hover:hover .pi-hifi-external) path:nth-of-type(3) { transform: translate(2.5px, -2.5px); }\n\n  /* ── reaction markers ─────────────────────────────────────────────────── */\n\n  /* thumbsup — approves */\n  .pi-hifi-thumbsup [data-part=\"hand\"] { transform-box: view-box; transform-origin: 22px 32px; }\n  :is(.pi-hifi-thumbsup:hover, .pi-hifi-thumbsup:focus-visible, .pi-hover:hover .pi-hifi-thumbsup) [data-part=\"hand\"] { transform: translateY(-2px) rotate(-8deg); }\n\n  /* warning — the mark pulses */\n  :is(.pi-hifi-warning:hover, .pi-hifi-warning:focus-visible, .pi-hover:hover .pi-hifi-warning) [data-part=\"mark\"] { animation: pi-pulse .7s ease-in-out infinite; }\n\n  /* dot — heartbeat */\n  :is(.pi-hifi-dot:hover, .pi-hifi-dot:focus-visible, .pi-hover:hover .pi-hifi-dot) circle:nth-of-type(2) { animation: pi-pulse 1s ease-in-out infinite; }\n  :is(.pi-hifi-dot:hover, .pi-hifi-dot:focus-visible, .pi-hover:hover .pi-hifi-dot) circle:nth-of-type(1) { animation: pi-ring 1.4s ease-out infinite; }\n\n  /* diamond / diamondFilled — pop (a diamond has 4-fold symmetry; 90° is a no-op) */\n  :is(.pi-hifi-diamond:hover, .pi-hifi-diamond:focus-visible, .pi-hover:hover .pi-hifi-diamond) path { transform: scale(1.1); }\n  :is(.pi-hifi-diamondFilled:hover, .pi-hifi-diamondFilled:focus-visible, .pi-hover:hover .pi-hifi-diamondFilled) path { transform: scale(1.08); }\n\n  /* caretRight / arrowRight — advance */\n  :is(.pi-hifi-caretRight:hover, .pi-hifi-caretRight:focus-visible, .pi-hover:hover .pi-hifi-caretRight) path { transform: translateX(3px); }\n  :is(.pi-hifi-arrowRight:hover, .pi-hifi-arrowRight:focus-visible, .pi-hover:hover .pi-hifi-arrowRight) path { animation: pi-nudge-x .7s ease-in-out infinite; }\n\n  /* ── research-graph notation ──────────────────────────────────────────── */\n\n  /* square — pop */\n  :is(.pi-hifi-square:hover, .pi-hifi-square:focus-visible, .pi-hover:hover .pi-hifi-square) rect { transform: scale(1.06); }\n\n  /* squareSplit — inner block fills in */\n  :is(.pi-hifi-squareSplit:hover, .pi-hifi-squareSplit:focus-visible, .pi-hover:hover .pi-hifi-squareSplit) rect:nth-of-type(2) { animation: pi-fill-in .45s cubic-bezier(.34, 1.56, .64, 1) both; }\n\n  /* squareRows / Cols / Grid — divisions draw in */\n  .pi-hifi-squareRows path,\n  .pi-hifi-squareCols path,\n  .pi-hifi-squareGrid path { stroke-dasharray: 80; }\n  :is(.pi-hifi-squareRows:hover, .pi-hifi-squareRows:focus-visible, .pi-hover:hover .pi-hifi-squareRows) path,\n  :is(.pi-hifi-squareCols:hover, .pi-hifi-squareCols:focus-visible, .pi-hover:hover .pi-hifi-squareCols) path,\n  :is(.pi-hifi-squareGrid:hover, .pi-hifi-squareGrid:focus-visible, .pi-hover:hover .pi-hifi-squareGrid) path { animation: pi-draw .55s ease forwards; }\n\n  /* rectangle — gentle width breathe */\n  :is(.pi-hifi-rectangle:hover, .pi-hifi-rectangle:focus-visible, .pi-hover:hover .pi-hifi-rectangle) rect { transform: scaleX(1.06); }\n\n  /* exchange — the two arrows swap past each other */\n  :is(.pi-hifi-exchange:hover, .pi-hifi-exchange:focus-visible, .pi-hover:hover .pi-hifi-exchange) path:nth-of-type(1) { transform: translateX(2.5px); }\n  :is(.pi-hifi-exchange:hover, .pi-hifi-exchange:focus-visible, .pi-hover:hover .pi-hifi-exchange) path:nth-of-type(2) { transform: translateX(-2.5px); }\n\n  /* wave — flows */\n  .pi-hifi-wave path { stroke-dasharray: 12 6; }\n  :is(.pi-hifi-wave:hover, .pi-hifi-wave:focus-visible, .pi-hover:hover .pi-hifi-wave) path { animation: pi-flow 1s linear infinite; }\n\n  /* pencil — writes */\n  .pi-hifi-pencil [data-part=\"pencil\"] { transform-box: view-box; transform-origin: 24px 24px; }\n  :is(.pi-hifi-pencil:hover, .pi-hifi-pencil:focus-visible, .pi-hover:hover .pi-hifi-pencil) [data-part=\"pencil\"] { animation: pi-write .6s ease-in-out infinite; }\n\n  /* ── keyframes ────────────────────────────────────────────────────────── */\n  @keyframes pi-spin     { to { transform: rotate(360deg); } }\n  @keyframes pi-pop      { 0% { transform: scale(.4); opacity: 0; } 60% { transform: scale(1.12); opacity: 1; } 100% { transform: scale(1); } }\n  @keyframes pi-peer-in  { 0% { transform: translateX(-6px) scale(.6); opacity: 0; } 100% { transform: translateX(0) scale(1); opacity: 1; } }\n  @keyframes pi-typing   { 0%, 60%, 100% { transform: translateY(0); } 30% { transform: translateY(-3px); } }\n  @keyframes pi-draw     { from { stroke-dashoffset: 80; } to { stroke-dashoffset: 0; } }\n  @keyframes pi-brain    { 0%, 100% { fill-opacity: .08; } 50% { fill-opacity: .2; } }\n  @keyframes pi-shimmer  { 0%, 100% { stroke-opacity: .5; } 50% { stroke-opacity: 1; } }\n  @keyframes pi-glow     { 0%, 100% { fill-opacity: .1; } 50% { fill-opacity: .26; } }\n  @keyframes pi-screen   { 0%, 100% { fill-opacity: .08; } 50% { fill-opacity: .22; } }\n  @keyframes pi-slide-x  { 0% { transform: translateX(-5px); opacity: .2; } 100% { transform: translateX(0); opacity: 1; } }\n  @keyframes pi-bounce-y { 0%, 100% { transform: translateY(0); } 45% { transform: translateY(4px); } }\n  @keyframes pi-grow-y   { 0% { transform: scaleY(0); } 100% { transform: scaleY(1); } }\n  @keyframes pi-ring     { 0% { transform: scale(.85); opacity: 1; } 70% { transform: scale(1.12); opacity: .35; } 100% { transform: scale(1.12); opacity: 0; } }\n  @keyframes pi-wobble   { 0% { transform: rotate(0); } 25% { transform: rotate(-22deg); } 55% { transform: rotate(14deg); } 80% { transform: rotate(-6deg); } 100% { transform: rotate(0); } }\n  @keyframes pi-scan     { 0%, 100% { transform: translate(0, 0); } 30% { transform: translate(3px, -2px); } 65% { transform: translate(-2px, 2px); } }\n  @keyframes pi-shake    { 0%, 100% { transform: translateX(0); } 20% { transform: translateX(-2.5px); } 40% { transform: translateX(2.5px); } 60% { transform: translateX(-1.5px); } 80% { transform: translateX(1.5px); } }\n  @keyframes pi-pulse    { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.14); } }\n  @keyframes pi-nudge-x  { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(3px); } }\n  @keyframes pi-fill-in  { 0% { transform: scale(.2); opacity: .2; } 100% { transform: scale(1); opacity: 1; } }\n  @keyframes pi-flow     { to { stroke-dashoffset: -18; } }\n  @keyframes pi-write    { 0%, 100% { transform: translate(0, 0); } 50% { transform: translate(1.5px, 1.5px); } }\n}\n"


def icon(name: str, cls: str | None = None) -> str:
    """Return a regular 24x24 icon as an inline `<svg class="ic ...">` string.

    Returns "" for unknown names (matches the council's previous `_icon`).
    `cls` appends an extra CSS class alongside any class baked into the icon.
    """
    spec = REGULAR.get(name)
    if spec is None:
        return ""
    classes = "ic"
    if spec.get("cls"):
        classes += " " + str(spec["cls"])
    if cls:
        classes += " " + cls
    return f'<svg class="{classes}" viewBox="0 0 24 24">{spec["body"]}</svg>'


def hifi(name: str, size: int = 48, cls: str = "ic-hifi") -> str:
    """Return a high-fidelity 48x48 display icon as a self-styled inline SVG."""
    body = HIFI.get(name)
    if body is None:
        return ""
    return (
        f'<svg class="{cls} pi-hifi pi-hifi-{name}" width="{size}" height="{size}" '
        f'viewBox="0 0 48 48" fill="none" stroke="currentColor" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{body}</svg>'
    )


def hifi_anim_css() -> str:
    """Return the hi-fi hover-animation CSS to inline in a <style> block."""
    return HIFI_ANIM_CSS


def names() -> list[str]:
    return list(REGULAR.keys())


def hifi_names() -> list[str]:
    return list(HIFI.keys())
